import { cancel_slot_booking } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    cancelDialog: Boolean,
    rowInfo: Object
  },
  components: {},
  data() {
    return {
      loading: false,
      fromMenu: false,
      fromDate: "",
      toDate: "",
      toMenu: false,
      minDate: new Date().toISOString().split("T")[0],
      commentsData: ""
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.fromDate = "";
      this.toDate = "";
    },
    async validate_date() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.booking_slot();
      }
    },
    async booking_slot() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(cancel_slot_booking, {
          input: {
            resource_id: this.rowInfo.resource_id,
            booking_id: this.rowInfo.booking_id,
            cancelled_comments: this.commentsData
          }
        }));
        var response = JSON.parse(result.data.cancel_slot_booking);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("SuccessMsg", response.Message);
          this.$refs.form.reset();
          this.$refs.form.resetValidation();
        } else {
          this.$emit("errorMsg", response.Message);
          this.loading = false;
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    fetch_current_date() {
      const currentDate = new Date();
      const year = currentDate.getFullYear();
      const month = String(currentDate.getMonth() + 1).padStart(2, "0"); // Months are zero-indexed
      const day = String(currentDate.getDate()).padStart(2, "0");
      const formattedDate = `${year}-${month}-${day}`;
      return formattedDate;
    },
    fetch_data() {
      var data = {};
      data = {
        start_epoch: this.slotInfo.start_epoch,
        end_epoch: this.slotInfo.end_epoch
      };
      return JSON.stringify(data);
    }
  }
};
